public sealed partial class CreditReminderSqlTests
{
    private const string PolicyPath="/api/admin/credit/reminder-policy";
    private static async Task<JsonNode> PolicyPage(HttpClient f)=>await Read(await f.GetAsync(PolicyPath));
    private static CreditReminderPolicyInput PolicyInput(JsonNode p,bool enabled=true,int[]? days=null,string? time="00:00")=>new(p["current"]?["version"]?.GetValue<string>(),enabled,enabled?(days??[0]):[],enabled?time:null,"SYNTHETIC-PRIVATE-POLICY-REVIEW",true);
    private static async Task<JsonNode> PolicyWrite(HttpClient f,CreditReminderPolicyInput input,string? command=null){var raw=System.Text.Json.JsonSerializer.Serialize(input,new System.Text.Json.JsonSerializerOptions(System.Text.Json.JsonSerializerDefaults.Web));var request=new HttpRequestMessage(HttpMethod.Post,PolicyPath+"/commands/"+(command??Id())){Content=new StringContent(raw,System.Text.Encoding.UTF8,"application/json")};request.Options.Set(new HttpRequestOptionsKey<string>("SyntheticReminderPostedBody"),raw);return await Read(await f.SendAsync(request));}
    [Fact]public async Task ReminderPolicyCasReplayHistoryOwnershipAndTamperAreAuthoritative()
    {
        using var f=await Staff("FinanceManager");var empty=await PolicyPage(f);Assert.Null(empty["current"]);Assert.False(empty["workerEnabled"]!.GetValue<bool>());var input=PolicyInput(empty,days:[-7,0,3],time:"09:30");var command=Id();var one=await PolicyWrite(f,input,command);Assert.Equal(1,one["policy"]!["current"]!["revision"]!.GetValue<int>());Assert.Equal(3,one["policy"]!["current"]!["dayOffsets"]!.AsArray().Count);var disabled=await PolicyWrite(f,PolicyInput(one["policy"]!,false));Assert.False(disabled["policy"]!["current"]!["enabled"]!.GetValue<bool>());var replay=await PolicyWrite(f,input,command);Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(one["policy"]!.ToJsonString(),replay["policy"]!.ToJsonString());using(var stale=await f.PostAsJsonAsync(PolicyPath+"/commands/"+Id(),input))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);using(var clash=await f.PostAsJsonAsync(PolicyPath+"/commands/"+command,input with{Note="Other payload"}))Assert.Equal(HttpStatusCode.Conflict,clash.StatusCode);
        var history=await Read(await f.GetAsync(PolicyPath+"/history"));Assert.Equal(2,history["items"]!.AsArray().Count);Assert.Null(history["nextBefore"]);using(var invalid=await f.GetAsync(PolicyPath+"/history?beforeRevision=01"))Assert.Equal(HttpStatusCode.BadRequest,invalid.StatusCode);using(var invalid=await f.GetAsync(PolicyPath+"?enabled=true"))Assert.Equal(HttpStatusCode.BadRequest,invalid.StatusCode);using(var reviewer=await Staff("CreditReviewer")){using var denied=await reviewer.GetAsync(PolicyPath);Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);}var stranger=await Customer();using(var customer=stranger.Client){using var denied=await customer.GetAsync(PolicyPath);Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);}var forged=JsonNode.Parse(System.Text.Json.JsonSerializer.Serialize(PolicyInput(disabled["policy"]!),new System.Text.Json.JsonSerializerOptions(System.Text.Json.JsonSerializerDefaults.Web)))!;forged["recipient"]="other";using(var invalid=await f.PostAsJsonAsync(PolicyPath+"/commands/"+Id(),forged))Assert.Equal(HttpStatusCode.BadRequest,invalid.StatusCode);
        await using var scope=sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();Assert.False(db.Database.HasPendingModelChanges());Assert.Equal(2,await db.ReminderPolicyRevisions.CountAsync());Assert.Equal(3,await db.ReminderPolicyOffsets.CountAsync());var down=await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.GetService<IMigrator>().MigrateAsync("20261028010854_PrivateChequeReminders"));Assert.Equal(51000,down.Number);var row=await db.ReminderPolicyRevisions.OrderBy(x=>x.Revision).FirstAsync();row.Enabled=false;Assert.Equal("credit_reminder_policy_history_immutable",(await Assert.ThrowsAsync<BusinessException>(()=>db.SaveChangesAsync())).Code);db.ChangeTracker.Clear();var offset=await db.ReminderPolicyOffsets.FirstAsync();db.Remove(offset);Assert.Equal("credit_reminder_policy_history_immutable",(await Assert.ThrowsAsync<BusinessException>(()=>db.SaveChangesAsync())).Code);db.ChangeTracker.Clear();var latest=V(disabled["policy"]!["current"]!,"id");await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ReminderPolicyRevisions] SET [ProtectedData]={new byte[]{1,2,3}} WHERE [Id]={latest}");using var bad=await f.GetAsync(PolicyPath);Assert.Equal(HttpStatusCode.ServiceUnavailable,bad.StatusCode);await Counts(0,0,0);
    }
    [Fact]public async Task ReminderPolicyAuditFailureRollsBackAndConcurrentInitialVersionsDoNotOverwrite()
    {
        using var f=await Staff("FinanceManager");var input=PolicyInput(await PolicyPage(f));var command=Id();await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_QA_ReminderPolicyAudit CHECK ([Action]<>'CREDIT_REMINDER_POLICY_ENABLE')");try{using var failed=await f.PostAsJsonAsync(PolicyPath+"/commands/"+command,input);Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_QA_ReminderPolicyAudit");}Assert.Null((await PolicyPage(f))["current"]);var race=await Task.WhenAll(f.PostAsJsonAsync(PolicyPath+"/commands/"+command,input),f.PostAsJsonAsync(PolicyPath+"/commands/"+Id(),input));Assert.Single(race,x=>x.IsSuccessStatusCode);Assert.Single(race,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var r in race)r.Dispose();await using var check=sql.Factory.Services.CreateAsyncScope();Assert.Equal(1,await check.ServiceProvider.GetRequiredService<CreditDbContext>().ReminderPolicyRevisions.CountAsync());Assert.Equal(1,await check.ServiceProvider.GetRequiredService<IdentityContext>().Audit.CountAsync(x=>x.Action=="CREDIT_REMINDER_POLICY_ENABLE"));
    }
    private static WebApplicationFactory<Program> AutomaticFactory(WebApplicationFactory<Program> parent,DateTimeOffset now,bool refuse=false)=>parent.WithWebHostBuilder(b=>b.ConfigureTestServices(services=>{services.AddSingleton<TimeProvider>(new FixedClock(now));services.AddSingleton(new CreditReminderDeliveryOptions(true));if(refuse)services.AddScoped<ICreditReminderNotificationWriter,RefusingWriter>();}));
    private static Task<CreditAutomaticReminderBatchResult> Sweep(WebApplicationFactory<Program> f)=>f.Services.GetRequiredService<CreditAutomaticReminderRunner>().RunAsync(CancellationToken.None);
    private static CreditAutomaticReminderRunner OtherRunner(WebApplicationFactory<Program> f)=>new(f.Services.GetRequiredService<IServiceScopeFactory>(),f.Services.GetRequiredService<TimeProvider>(),new(true),NullLogger<CreditAutomaticReminderRunner>.Instance);
    [Fact]public async Task AutomaticReminderRequiresExplicitPolicyTimeAndHeldCommittedSourceAndDeduplicatesReplicas()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var due=V(s.Cheques[0],"dueDate");var when=DateTimeOffset.Parse(due+"T06:00:00Z");await using var worker=AutomaticFactory(sql.Factory,when);Assert.Equal(0,(await Sweep(worker)).Sent);var policy=await PolicyWrite(f,PolicyInput(await PolicyPage(f),time:"09:31"));Assert.Equal(0,(await Sweep(worker)).Sent);var before=await PolicyWrite(f,PolicyInput(policy["policy"]!,time:"09:30"));Assert.Equal(0,(await Sweep(sql.Factory)).Sent);var race=await Task.WhenAll(Sweep(worker),OtherRunner(worker).RunAsync(CancellationToken.None));Assert.Equal(1,race.Sum(x=>x.Sent));Assert.Equal(0,race.Sum(x=>x.Failed));Assert.Equal(0,(await Sweep(worker)).Sent);var inbox=await Read(await customer.GetAsync("/api/notifications/credit-reminders"));Assert.Single(inbox["items"]!.AsArray());Assert.DoesNotContain("policy=",inbox.ToJsonString());Assert.DoesNotContain("SYSTEM_",inbox.ToJsonString());await using var scope=worker.Services.CreateAsyncScope();var sp=scope.ServiceProvider;var db=sp.GetRequiredService<CreditDbContext>();var ev=await db.ReminderEvents.SingleAsync();Assert.Equal(CreditAutomaticReminderService.Actor,ev.ActorId);Assert.Equal(ChequeReportRules.Date(due),ev.CivilDay);Assert.Equal(1,await sp.GetRequiredService<IdentityContext>().Audit.CountAsync(x=>x.Action=="CREDIT_CHEQUE_REMINDER_AUTOMATIC"));Assert.Equal(OrderState.CreditApproved,(await sp.GetRequiredService<SalesDbContext>().Orders.SingleAsync()).State);Assert.Equal(0,await sp.GetRequiredService<SalesDbContext>().OrderCashPayments.CountAsync());var disabled=await PolicyWrite(f,PolicyInput(before["policy"]!,false));Assert.Equal(0,(await Sweep(worker)).Sent);Assert.Equal(1,await db.ReminderEvents.CountAsync());
    }
    [Fact]public async Task AutomaticReminderNotificationAndAuditFailuresLeaveNoDeliveryAndRetryCanCommit()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var due=V(s.Cheques[0],"dueDate");var when=DateTimeOffset.Parse(due+"T06:00:00Z");await PolicyWrite(f,PolicyInput(await PolicyPage(f),time:"09:30"));await using(var refusal=AutomaticFactory(sql.Factory,when,true)){var result=await Sweep(refusal);Assert.Equal(0,result.Sent);Assert.Equal(1,result.Failed);}await Counts(0,0,0);await using var worker=AutomaticFactory(sql.Factory,when);await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_QA_AutomaticReminderAudit CHECK ([Action]<>'CREDIT_CHEQUE_REMINDER_AUTOMATIC')");try{var result=await Sweep(worker);Assert.Equal(0,result.Sent);Assert.Equal(1,result.Failed);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_QA_AutomaticReminderAudit");}await Counts(0,0,0);Assert.Equal(1,(await Sweep(worker)).Sent);await using var check=sql.Factory.Services.CreateAsyncScope();Assert.Equal(1,await check.ServiceProvider.GetRequiredService<CreditDbContext>().ReminderCommands.CountAsync());Assert.Equal(1,await check.ServiceProvider.GetRequiredService<NotificationsDbContext>().CreditInbox.CountAsync());
    }
    [Fact]public async Task AutomaticReminderRechecksPolicyAndLedgerAfterCandidateScanAndNeverBackfillsMissedDays()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var due=V(s.Cheques[0],"dueDate");var when=DateTimeOffset.Parse(due+"T06:00:00Z");var one=await PolicyWrite(f,PolicyInput(await PolicyPage(f),time:"09:30"));await using var worker=AutomaticFactory(sql.Factory,when);CreditAutomaticReminderCandidate candidate;await using(var reader=worker.Services.CreateAsyncScope())candidate=Assert.Single(await reader.ServiceProvider.GetRequiredService<CreditAutomaticReminderService>().CandidatesAsync(V(one["policy"]!["current"]!,"id"),due,null,CancellationToken.None));var disabled=await PolicyWrite(f,PolicyInput(one["policy"]!,false));await using(var scope=worker.Services.CreateAsyncScope()){var sp=scope.ServiceProvider;var result=await sp.GetRequiredService<CreditReminderCoordinator>().Atomic(()=>sp.GetRequiredService<CreditAutomaticReminderService>().SendAsync(candidate,V(one["policy"]!["current"]!,"id"),due,CancellationToken.None),CancellationToken.None);Assert.Null(result);}await PolicyWrite(f,PolicyInput(disabled["policy"]!,time:"09:30"));await using(var tomorrow=AutomaticFactory(sql.Factory,when.AddDays(1)))Assert.Equal(0,(await Sweep(tomorrow)).Sent);var deposit=await CreditScheduleQa.Read(await f.PostAsJsonAsync(Base(s)+"/cheques/"+V(s.Cheques[0],"id")+"/commands/"+Id(),new MoveChequeInput(V(s.Cheques[0],"version"),"Deposit","Synthetic prerequisite deposit",DateTimeOffset.UtcNow,true,true)));await CreditScheduleQa.Read(await f.PostAsJsonAsync(Base(s)+"/cheques/"+V(s.Cheques[0],"id")+"/commands/"+Id(),new MoveChequeInput(V(deposit["cheque"]!,"version"),"ReportCollection","Synthetic collected report prevents automatic reminder",DateTimeOffset.UtcNow,true,true)));var held=await Sweep(worker);Assert.Equal(0,held.Sent);Assert.Equal(1,held.Skipped);await Counts(0,0,0);
    }
    [Fact]public async Task ManualAndAutomaticReminderShareOneCivilDayLimitAndExplicitNextDayCanSendAgain()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var due=V(s.Cheques[0],"dueDate");var when=DateTimeOffset.Parse(due+"T06:00:00Z");await PolicyWrite(f,PolicyInput(await PolicyPage(f),days:[0,1],time:"09:30"));await using var worker=AutomaticFactory(sql.Factory,when);CreditReminderPage preview;
        await using(var scope=worker.Services.CreateAsyncScope())preview=await scope.ServiceProvider.GetRequiredService<CreditReminderCoordinator>().ReadAsync(x=>x.PageAsync(s.Owner,s.Order,V(s.Cheques[0],"id"),true,CancellationToken.None),CancellationToken.None);
        async Task<bool> Manual(){await using var scope=worker.Services.CreateAsyncScope();try{await scope.ServiceProvider.GetRequiredService<CreditReminderCoordinator>().SendAsync("QA_MANUAL_FINANCE",s.Owner,s.Order,preview.Cheque.Id,Id(),new(preview.OrderVersion,preview.Cheque.Version,preview.PreviewFingerprint,"Synthetic manual/automatic race",true),"/synthetic-only","synthetic-only",CancellationToken.None);return true;}catch(BusinessException e)when(e.Code.Contains("conflict",StringComparison.Ordinal)){return false;}}
        var manual=Manual();var automatic=Sweep(worker);await Task.WhenAll(manual,automatic);Assert.Equal(1,(await manual?1:0)+(await automatic).Sent);Assert.Equal(0,(await automatic).Failed);
        await using(var check=worker.Services.CreateAsyncScope()){var sp=check.ServiceProvider;Assert.Equal(1,await sp.GetRequiredService<CreditDbContext>().ReminderEvents.CountAsync());Assert.Equal(1,await sp.GetRequiredService<NotificationsDbContext>().CreditInbox.CountAsync());Assert.Equal(1,await sp.GetRequiredService<IdentityContext>().Audit.CountAsync(x=>x.Action=="CREDIT_CHEQUE_REMINDER"||x.Action=="CREDIT_CHEQUE_REMINDER_AUTOMATIC"));}
        await using(var tomorrow=AutomaticFactory(sql.Factory,when.AddDays(1))){Assert.Equal(1,(await Sweep(tomorrow)).Sent);Assert.Equal(0,(await Sweep(tomorrow)).Sent);}await using var final=sql.Factory.Services.CreateAsyncScope();var db=final.ServiceProvider.GetRequiredService<CreditDbContext>();Assert.Equal(2,await db.ReminderEvents.CountAsync());Assert.Equal(2,await db.ReminderEvents.Select(x=>x.CivilDay).Distinct().CountAsync());Assert.Equal(2,await final.ServiceProvider.GetRequiredService<NotificationsDbContext>().CreditInbox.CountAsync());
    }

}
